// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address requester, bytes32 digest, uint256 utxoSize, bytes calldata redeemerOutputScript, uint256 requestedFee, bytes calldata outpoint) public {
        vm.assume(utxoSize <= 1e30);
        // Ensure the call does not revert by only calling with approved loggers enabling returns
        vm.assume(caller != address(0));
        bool isApproved = c.approvedToLog(caller);
        vm.prank(caller);
        bool result = c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint);
        // The general rule: logRedemptionRequested should return false for unapproved callers and true for approved callers
        assertTrue(result == isApproved);
    }
}

